      SUBROUTINE EXILECC     TRANSFER DATA TO END OF ARRAYS FOR REPROCESSINGCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'LIMITS.CIN'C------------------------------------------------------------------------      EQUIVALENCE     (FAKE,LAKE)C      NSHFT = NELLIM - NEL      IBIG = ISTOR(NEL+1) - 1      ISHFT = IDLIM - IBIGC      IOLD = 0      NDEF = 0      DO 100 NN = 1, NEL      I = ISTOR(NN)      TYPE = IDATA(I)      IF (NUSE .EQ. 0) THEN        IF (I .LE. IOLD) GO TO 100      ELSE        IF (TYPE .NE. 24 .AND. NDEF .GE. 1) GO TO 100      ENDIF      IOLD = MAX0(I,IOLD)      IF (TYPE .GT. 0) CALL SKETCH(NN)C      IF (TYPE .EQ. 2 .OR. TYPE .EQ. 3 .OR. TYPE .EQ. 4     1    .OR. TYPE .EQ. 5 .OR. TYPE .EQ. 7 .OR. TYPE .EQ. 8     2    .OR. TYPE .EQ. 10 .OR. TYPE .EQ. 11 .OR. TYPE .EQ. 14      3    .OR. TYPE .EQ. 16 .OR. TYPE .EQ. 18 .OR. TYPE .EQ. 19      4    .OR. TYPE .EQ. 20 .OR. TYPE .EQ. 25 .OR. TYPE .EQ. 28      5    .OR. TYPE .EQ. 29 .OR. TYPE .EQ. 30 .OR. TYPE .EQ. 34      6    .OR. TYPE .EQ. 35 .OR. TYPE .EQ. 36 .OR. TYPE .EQ. 42)      7     GO TO 10      IF (TYPE .EQ. 22) GO TO 30      IF (TYPE .EQ. 23) GO TO 40      IF (TYPE .EQ. 24) GO TO 50      IF (TYPE .EQ. 50 .OR. TYPE .EQ. 51 .OR. TYPE .EQ. 52) GO TO 60      GO TO 100CC     PHYSICAL ELEMENTC   10 DO 15 J = 1, NPARMS      IADR = I + J      KREG = IDATA(IADR)      KTIE = TIE(IADR)      IF (KTIE .EQ. 100) THEN        KREG = KREG + ISHFT        LAKE = KREG        DATA(IADR) = FAKE      ENDIF   15 CONTINUE      GO TO 100CC     IDENTIFICATION OF MATRIX ELEMENTC   30 JCODE = IDATA(I+2)       JTIE = TIE(I+2)      IF (JTIE .EQ. 100) JCODE = JCODE + ISHFT      LAKE = JCODE      DATA(I+2) = FAKE      GO TO 100CC     ALGEBRAIC COMBINATIONC   40 K1TIE = TIE(I+1)      K2TIE = TIE(I+2)      JTIE = TIE(I+4)      K1REG = IDATA(I+1)      K2REG = IDATA(I+2)      JREG = IDATA(I+4)      IF (K1TIE .EQ. 100) K1REG = K1REG + ISHFT      IF (K2TIE .EQ. 100) K2REG = K2REG + ISHFT      IF (JTIE .EQ. 100) JREG = JREG + ISHFT      LAKE = K1REG      DATA(I+1) = FAKE      LAKE = K2REG      DATA(I+2) = FAKE      LAKE = JREG      DATA(I+4) = FAKE      GO TO 100CC     DEFINED SECTIONC   50 JDEF = IDATA(I+1)      IF (JDEF .EQ. 1) NDEF = NDEF + 1      IF (JDEF .EQ. 2) NDEF = NDEF - 1       GO TO 100CC     HISTOGRAMC   60 IPT5 = IPTOJ(5)      IF (IPT5 .NE. 0 .AND. TIE(I+IPT5) .EQ. 100) THEN        NCOO = IDATA(I+IPT5)        NCOO = NCOO + ISHFT        LAKE = NCOO        DATA(I+IPT5) = FAKE      ENDIF      GO TO 100C  100 CONTINUEC      DO 110 NN = 1, NEL      ISTOR(NN) = ISTOR(NN) + ISHFT  110 CONTINUEC      IF (NUSE .NE. 0) NUSE = NUSE + NSHFTC      DO 120 NN = 1, NEL      NOLD = NEL - NN + 1      NNEW = NOLD + NSHFT      ISTOR(NNEW) = ISTOR(NOLD)      LABEL(NNEW) = LABEL(NOLD)      NDESCR(NNEW) = NDESCR(NOLD)  120 CONTINUEC      DO 130 IB = 1, IBIG      I2 = IDLIM - IB + 1      I1 = IBIG - IB + 1      DATA(I2) = DATA(I1)      TIE(I2) = TIE(I1)  130 CONTINUEC      RETURN      END